class ProductionMethods(unittest.TestCase):
 def test_production_methods_and_lifetimes(self):
  prefix=fixture.HARNESS[:fixture.HARNESS.index('int main(')].replace('kEntityBlockSize = 0xD00','kEntityBlockSize = 0x3000')
  prefix=re.sub(r'namespace GameFileReader \{\nTextReadResult[\s\S]*?\n\}\n\}', '',prefix,count=1)
  with tempfile.TemporaryDirectory(prefix='api400-production-')as d:
   binary=build_lua_harness(source_root=fixture.SOURCE,workdir=Path(d),harness_source=prefix+MAIN)
   for scene in ('normal','badguard','dead','crossbase'):
    with self.subTest(scene=scene):
     r=subprocess.run([str(binary),scene],capture_output=True,text=True);self.assertEqual(r.returncode,0,r.stdout+r.stderr)
